import{_ as e,a,e as n,l as r,at as o,Q as s,t as i}from"./chunks/framework.D7hrsxJP.js";const P=JSON.parse('{"title":"前端性能衡量标准","description":"前端性能衡量标准","frontmatter":{"title":"前端性能衡量标准","description":"前端性能衡量标准","tags":["frontend","vital"]},"headers":[],"relativePath":"frontend/performance/WebVitals.md","filePath":"frontend/performance/WebVitals.md","lastUpdated":1761045430000}'),l={name:"frontend/performance/WebVitals.md"},h={id:"frontmatter-title",tabindex:"-1"};function g(d,t,b,m,c,f){return n(),a("div",null,[t[1]||(t[1]=r("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /vite-press/frontend/performance/WebVitals.md for this page in Markdown format",-1)),r("h1",h,[s(i(d.$frontmatter.title)+" ",1),t[0]||(t[0]=r("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),t[2]||(t[2]=o('<h2 id="一、核心-web-vitals-关键用户体验指标" tabindex="-1">一、核心 Web Vitals（关键用户体验指标） <a class="header-anchor" href="#一、核心-web-vitals-关键用户体验指标" aria-label="Permalink to “一、核心 Web Vitals（关键用户体验指标）”">​</a></h2><table tabindex="0"><thead><tr><th>指标名</th><th>含义</th><th>衡量点</th><th>理想值</th></tr></thead><tbody><tr><td><strong>LCP（Largest Contentful Paint）</strong></td><td>最大内容绘制时间</td><td>页面最大内容元素出现在视口中所需时间 （加载性能）</td><td>≤ 2.5s</td></tr><tr><td><strong>FID（First Input Delay）</strong></td><td>首次输入延迟</td><td>用户首次交互（点击等）到浏览器响应之间的延迟</td><td>≤ 100ms</td></tr><tr><td><strong>INP（Interaction to Next Paint）</strong></td><td>与用户交互后的响应速度（取代 FID）</td><td>所有交互中响应最慢的一次 （交互性能）</td><td>≤ 200ms</td></tr><tr><td><strong>CLS（Cumulative Layout Shift）</strong></td><td>累计布局偏移</td><td>页面布局在加载过程中的跳动程度 （视觉稳定性）</td><td>≤ 0.1</td></tr></tbody></table><h2 id="二、加载性能指标" tabindex="-1">二、加载性能指标 <a class="header-anchor" href="#二、加载性能指标" aria-label="Permalink to “二、加载性能指标”">​</a></h2><table tabindex="0"><thead><tr><th>指标名</th><th>含义</th></tr></thead><tbody><tr><td><strong>TTFB（Time to First Byte）</strong></td><td>首字节到达时间，反映服务端响应速度</td></tr><tr><td><strong>FCP（First Contentful Paint）</strong></td><td>页面首次渲染文字/图像的时间</td></tr><tr><td><strong>DOMContentLoaded</strong></td><td>DOM 解析完成的时间</td></tr><tr><td><strong>Load Event Time</strong></td><td>所有资源加载完成的时间</td></tr><tr><td><strong>Fully Loaded</strong></td><td>包括懒加载等所有异步加载完成的时间</td></tr><tr><td><strong>Resource Load Time</strong></td><td>静态资源（CSS、JS、图片等）加载耗时</td></tr></tbody></table><h2 id="三、运行时性能指标" tabindex="-1">三、运行时性能指标 <a class="header-anchor" href="#三、运行时性能指标" aria-label="Permalink to “三、运行时性能指标”">​</a></h2><table tabindex="0"><thead><tr><th>指标名</th><th>含义</th></tr></thead><tbody><tr><td><strong>JS 执行耗时</strong></td><td>JavaScript 执行的总时间</td></tr><tr><td><strong>Main Thread Blocking Time</strong></td><td>主线程被阻塞时间</td></tr><tr><td><strong>FPS（Frames Per Second）</strong></td><td>页面流畅度（60FPS 为理想值）</td></tr><tr><td><strong>Long Tasks</strong></td><td>主线程中执行超过 50ms 的任务数量</td></tr><tr><td><strong>Memory Usage</strong></td><td>页面内存占用量</td></tr><tr><td><strong>CPU 使用率</strong></td><td>高计算场景如动画、复杂渲染时的 CPU 压力</td></tr></tbody></table><h2 id="四、用户体验感知指标" tabindex="-1">四、用户体验感知指标 <a class="header-anchor" href="#四、用户体验感知指标" aria-label="Permalink to “四、用户体验感知指标”">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>含义</th></tr></thead><tbody><tr><td><strong>感知加载速度</strong></td><td>页面是否提供骨架屏或加载反馈</td></tr><tr><td><strong>可交互时间</strong></td><td>页面何时可以响应用户操作</td></tr><tr><td><strong>视觉稳定性</strong></td><td>页面加载是否抖动跳动</td></tr><tr><td><strong>动画流畅性</strong></td><td>页面过渡与滚动是否顺畅</td></tr></tbody></table><h2 id="五、常用性能评测工具" tabindex="-1">五、常用性能评测工具 <a class="header-anchor" href="#五、常用性能评测工具" aria-label="Permalink to “五、常用性能评测工具”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>功能</th></tr></thead><tbody><tr><td><strong>Lighthouse</strong></td><td>自动性能评分与优化建议</td></tr><tr><td><strong>PageSpeed Insights</strong></td><td>基于 Web Vitals 的在线分析</td></tr><tr><td><strong>WebPageTest</strong></td><td>多网络、多区域真实加载测试</td></tr><tr><td><strong>Chrome DevTools - Performance</strong></td><td>精确分析执行帧、脚本、帧率等</td></tr><tr><td><strong>Webpack Bundle Analyzer</strong></td><td>打包分析，识别过大模块</td></tr><tr><td><strong>Sentry、LogRocket</strong></td><td>RUM（真实用户监控）解决方案</td></tr></tbody></table>',10))])}const y=e(l,[["render",g]]);export{P as __pageData,y as default};
